import wollok.game.*

object barraDeVida {
    var imagen = "vida100.png"

    var property position = game.at(4, 47)

    method image() = imagen

    method actualizar(vida) {
        if (vida <= 100 and vida >75) {
            imagen = "vida100.png"
        } else if (vida <= 75 and vida>50) {
            imagen = "vida75.png"
        } else if (vida <= 50 and vida > 25) {
            imagen = "vida50.png"
        } else if (vida <= 25 and vida > 0) {
            imagen = "vida25.png"
        } else {
            imagen = "vida0.png"
        }
    }
}

