}

class Entidad{
    var property vida
    var property position
    var property ancho
    var property alto
    var property imagenNormal
    var property imagenCaminando
    var property imagenActual
    var property movimientoId = 0


    method colisionaCon(objeto){
        const entIzquierda=position.x()
        const entDerecha=position.x()+ancho
        const entAbajo=position.y()
        const entArriba=position.y()+alto

        const objIzquierda = objeto.position().x()
        const objDerecha = objeto.position().x() + objeto.ancho()
        const objAbajo = objeto.position().y()
        const objArriba = objeto.position().y() + objeto.alto()

        const seCruzanEnX = (entIzquierda < objDerecha) and (entDerecha > objIzquierda)
        const seCruzanEnY = (entAbajo < objArriba) and (entArriba > objAbajo)

        return seCruzanEnX and seCruzanEnY
    }

    method image() = imagenActual

    method moverA(nuevaPosicion) {
    if (nuevaPosicion.x().between(0, 49) and
        nuevaPosicion.y().between(0, 49)) {

        position = nuevaPosicion
        self.despuesDeMoverse()

        movimientoId += 1
        const idActual = movimientoId

        imagenActual = imagenCaminando

        game.schedule(700, {
            if (movimientoId == idActual) {
                imagenActual = imagenNormal
            }
        })
    }
}

    method despuesDeMoverse()

}

class Rick inherits Entidad(
    vida = 100,
    position = game.origin(),
    ancho = 2,
    alto = 5.5,
    imagenNormal = "rick2.png",
    imagenCaminando = "rick_caminando.gif",
    imagenActual = "rick2.png"
) 
{
    var property tieneLiquidoPortal = false
    var property danio = 25
    var property tieneEspinaca = false



    method actualizarVida(){
        barraDeVida.actualizar(vida)
    }

    method curarse(cantidad){
        vida = (vida + cantidad).min(100)
        self.actualizarVida()
    }

    method conseguirLiquidoPortal(){
        tieneLiquidoPortal=true
    }

    method gastarLiquidoPortal(){
        tieneLiquidoPortal=false
    }

    method teletransportarse(){
        position=portalBueno.destino()
    }

    method recibirDanio(cantidad) {
        vida = (vida-cantidad).max(0)
        self.actualizarVida()
        if(vida==0){
            game.removeVisual(self)
            game.addVisual(pantallaDerrota)
        }
    }

    method mostrarVida()=vida

    override method despuesDeMoverse() {

        const pocionActual = gestorNiveles.pocionActual()
        const liquidoActual = gestorNiveles.liquidoPortalActual()
        const espinacaActual = gestorNiveles.espinacaActual()
        const mortyActual = gestorNiveles.mortyActual()

        if (game.allVisuals().contains(pocionActual) and self.colisionaCon(pocionActual))
            pocionActual.meConsumio(self)

        if (game.allVisuals().contains(liquidoActual) and self.colisionaCon(liquidoActual))
            liquidoActual.meConsumio(self)

        if (game.allVisuals().contains(portalBueno) and self.colisionaCon(portalBueno))
            portalBueno.meConsumio(self)

        if (game.allVisuals().contains(portalMalo) && self.colisionaCon(portalMalo)) 
            portalMalo.meConsumio(self)

        if (game.allVisuals().contains(portalNulo) && self.colisionaCon(portalNulo)) 
            portalNulo.meConsumio(self)

        if (game.allVisuals().contains(espinacaActual) and self.colisionaCon(espinacaActual))
            espinacaActual.meConsumio(self)

        if (mortyActual != null and
            game.allVisuals().contains(mortyActual) and
            self.colisionaCon(mortyActual))
            mortyActual.meConsumio(self)


    }

    method atacar(){
        const enemigoActual=gestorNiveles.enemigoActual()
        if(game.hasVisual(enemigoActual) and self.colisionaCon(enemigoActual) and enemigoActual != null)
            enemigoActual.recibirDanio(danio)
        if(game.hasVisual(zorro) and self.colisionaCon(zorro))
            zorro.recibirDanio(danio)
    }

    method aumentarDanio(cantidad) {
        danio += cantidad
    }

    method conseguirEspinaca(){ 
        tieneEspinaca=true
        game.addVisual(iconoEspinaca)
    }

    method perderEspinaca(){
        tieneEspinaca=false
        game.removeVisual(iconoEspinaca)
    }

    method consumirEspinaca(){
        if(tieneEspinaca){
            tieneEspinaca=false
            game.removeVisual(iconoEspinaca)
            self.aumentarDanio(25)
            game.say(self, "Espinaca consumida")
        }
    }
}

const rick = new Rick()

const enemigo = new Enemigo()

class Enemigo inherits Entidad(
    vida = 50,
    position = game.at(35, 38),
    ancho = 2,
    alto = 5.5,
    imagenNormal = "EnemigoAzul.png",
    imagenCaminando = "enemigoAzulCaminando.gif",
    imagenActual = "EnemigoAzul.png"
) 
{
    var property danio = 25

    override method despuesDeMoverse(){}

    method estaVivo()=vida>0

    method recibirDanio(cantidad){
        vida=(vida-cantidad).max(0)
        if(vida==0){
            game.removeVisual(self)
            danio = 0
        }
    }


    method perseguir() {
        if (position.x() < rick.position().x())
            self.moverA(position.right(1))
        else if (position.x() > rick.position().x())
            self.moverA(position.left(1))
        else if (position.y() < rick.position().y())
            self.moverA(position.up(1))
        else if (position.y() > rick.position().y())
            self.moverA(position.down(1))
    }

    method atacar(){
        if(rick.mostrarVida() > 0 and self.colisionaCon(rick)){
                rick.recibirDanio(danio)
            }
    }
}

class Zorro inherits Entidad(
    vida = 50,
    position = game.at(5, 40),
    ancho = 2,
    alto = 5.5,
    imagenNormal = "zorro.png",
    imagenCaminando = "zorro.png",
    imagenActual = "zorro.png"
) 
{

    override method despuesDeMoverse(){}

    method perseguirEspinaca(){
        if(self.estaVivo() and rick.tieneEspinaca()){
            if(position.x()<rick.position().x())
                self.moverA(position.right(1))
            else if(position.x()>rick.position().x())
                self.moverA(position.left(1))
            else if(position.y()<rick.position().y())
                self.moverA(position.up(1))
            else if(position.y()>rick.position().y())
                self.moverA(position.down(1))

            if(self.colisionaCon(rick)){
                rick.perderEspinaca()
                game.say(rick, "Zorro no te lo lleves!!")
            }
        }
    }

    method estaVivo()=vida>0

    method recibirDanio(cantidad){
        if(self.estaVivo()){
            vida=(vida-cantidad).max(0)

            if(vida==0){
                game.removeVisual(self)
            }
        }
    }
}

const zorro=new Zorro()

