object gestorNiveles {
    var nivelActual = nivel1

    method mortyActual() = nivelActual.morty()
    method pocionActual() = nivelActual.pocion()
    method liquidoPortalActual() = nivelActual.liquidoPortal()
    method espinacaActual() = nivelActual.espinaca()
    method enemigoActual() = nivelActual.enemigo()


    method cambiarNivel() {
        nivelActual.descargar()

        if (nivelActual == nivel2) {
            nivelActual = nivel3
        }
        else {
            nivelActual = nivel2
        }

        nivelActual.cargar()
    }
}

