program PepitaGame {
    game.title("Rick a través del multiverso")
    game.height(50)
    game.width(50)
    game.cellSize(100)

    game.addVisual(fondo)
    game.addVisual(rick)
    // game.addVisual(enemigo)
    game.addVisual(barraDeVida)
    game.addVisual(zorro)

    rick.actualizarVida()

    nivel1.cargar()

    const movimientoEnemigo=game.tick(250, {const enemigoAct = gestorNiveles.enemigoActual()
        if(enemigoAct!=null and enemigoAct.estaVivo() and game.hasVisual(enemigoAct)){enemigoAct.perseguir()}}, false)

    const ataqueEnemigo=game.tick(1750, {const enemigoAct=gestorNiveles.enemigoActual()
        if(enemigoAct != null and enemigoAct.estaVivo()
        and game.hasVisual(enemigoAct))
            {enemigoAct.atacar()}}, false)

    const movimientoZorro=game.tick(400, {zorro.perseguirEspinaca()}, false)

    movimientoEnemigo.start()
    ataqueEnemigo.start()
    movimientoZorro.start()

    keyboard.up().onPressDo({ rick.moverA(rick.position().up(1)) })
    keyboard.down().onPressDo({ rick.moverA(rick.position().down(1)) })
    keyboard.left().onPressDo({ rick.moverA(rick.position().left(1)) })
    keyboard.right().onPressDo({ rick.moverA(rick.position().right(1)) })

    keyboard.enter().onPressDo({
    if (rick.tieneLiquidoPortal()) {
        if (!game.hasVisual(portalBueno))
            game.addVisual(portalBueno)

        if (!game.hasVisual(portalNulo))
            game.addVisual(portalNulo)

        if (!game.hasVisual(portalMalo))
            game.addVisual(portalMalo)

        rick.gastarLiquidoPortal()
    }
})

    keyboard.space().onPressDo({rick.atacar()})
    keyboard.e().onPressDo({rick.consumirEspinaca()})
    game.start()
}

import wollok.game.*
