class Nivel {
    const fondoImagen
    const pocion
    const liquidoPortal
    const morty
    const espinaca
    const enemigo

    method pocion() = pocion
    method liquidoPortal() = liquidoPortal
    method morty() = morty
    method espinaca()= espinaca
    method enemigo()=enemigo

    method cargar() {
        fondo.imagen(fondoImagen)
        if (pocion != null) {
            game.addVisual(pocion)
        }
        if (liquidoPortal != null) {
            game.addVisual(liquidoPortal)
        }
        if (espinaca != null) {
            game.addVisual(espinaca)
        }
        if (morty != null) {
            game.addVisual(morty)
        }
        if(enemigo != null){
            game.addVisual(enemigo)
        }
    }

    method descargar() {
        if (pocion != null) {
            game.removeVisual(pocion)
        }
        if (liquidoPortal != null) {
            game.removeVisual(liquidoPortal)
        }
        if (espinaca != null) {
            game.removeVisual(espinaca)
        }
        if (morty != null) {
            game.removeVisual(morty)
        }
        if(enemigo != null and game.hasVisual(enemigo)){
            game.removeVisual(enemigo)
        }
    }
}

