class Portal{
    var property position
    var habilitado=false
    const property ancho = 1.2
    const property alto = 2

    method image()

    method habilitar(){
        habilitado=true
    }

    method estaHabilitado()=habilitado

    method destino()

    method meConsumio(personaje)

    method atraversa(personaje)

}

class PortalBueno inherits Portal(position=game.at(3, 40)){
    override method image()="Portalazo.gif"

    override method destino() = game.at(5, 5)

    override method meConsumio(personaje) {
        game.removeVisual(self)
        gestorNiveles.cambiarNivel()
    }

    override method atraversa(personaje) {
        if (habilitado) personaje.teletransportarse()
    }
}

const portalBueno=new PortalBueno()

