    override method image()="normalazo.gif"
    override method habilitar(){
        habilitado = true
    }

    override method destino(){}

    override method meConsumio(personaje){
        game.removeVisual(self)
    }

    override method atraversa(personaje){}
}

const portalNulo = new PortalNulo()

class PortalMalo inherits Portal(position=game.at(43, 40)){
    override method image()="malazo.gif"

    override method destino(){}

    override method habilitar(){
        habilitado = true
    }

    override method meConsumio(personaje) {
        personaje.recibirDanio(25)
        game.removeVisual(self)
    }

    override method atraversa(personaje) {}
}

